def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def to_minutes(text):
        if text == "":
            return 0
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def to_time(total):
        hour = total // 60
        minute = total % 60
        h = str(hour)
        m = str(minute)
        if hour < 10:
            h = "0" + h
        if minute < 10:
            m = "0" + m
        return h + ":" + m

    def offset_minutes(text):
        if text == "":
            return 0
        sign = 1
        if text[0] == "-":
            sign = -1
        hours = int(text[1:3])
        mins = int(text[4:6])
        return sign * (hours * 60 + mins)

    def get_day_info(data, day):
        items = data.get("days", [])
        want = day[:3].lower()
        if len(items) == 0:
            return {}
        for item in items:
            if item.get("day", "").lower() == want:
                return item
        return items[0]

    def merge_intervals(intervals):
        if len(intervals) == 0:
            return []
        intervals = sorted(intervals)
        merged = [list(intervals[0])]
        for item in intervals[1:]:
            s = item[0]
            e = item[1]
            last = merged[-1]
            if s <= last[1]:
                if e > last[1]:
                    last[1] = e
            else:
                merged.append([s, e])
        return merged

    def free_from_busy(start, end, busy):
        free = []
        current = start
        for item in busy:
            s = item[0]
            e = item[1]
            if e <= start:
                continue
            if s >= end:
                break
            if s > current:
                free.append([current, s])
            if e > current:
                current = e
            if current >= end:
                break
        if current < end:
            free.append([current, end])
        return free

    def intersect_lists(a, b):
        result = []
        i = 0
        j = 0
        while i < len(a) and j < len(b):
            s = max(a[i][0], b[j][0])
            e = min(a[i][1], b[j][1])
            if s < e:
                result.append([s, e])
            if a[i][1] < b[j][1]:
                i += 1
            else:
                j += 1
        return result

    def ceil_quarter(value):
        return ((value + 14) // 15) * 15

    earliest_min = 0
    if earliest != "":
        earliest_min = to_minutes(earliest)

    latest_min = 24 * 60
    if latest_end != "":
        latest_min = to_minutes(latest_end)

    starts = {}
    user_offset = None

    for day in days:
        people = [""]
        for person in attendees:
            people.append(person)

        day_free = []
        first = True

        for person in people:
            data = api.read_calendar(person, day)
            info = get_day_info(data, day)
            offset = offset_minutes(data.get("utc_offset", ""))
            if user_offset is None:
                user_offset = offset_minutes(api.read_calendar("", day).get("utc_offset", "")) if person != "" else offset

            shift = user_offset - offset

            working = info.get("working_hours", "")
            if working == "":
                work_start = 0
                work_end = 24 * 60
            else:
                parts = working.split("-")
                work_start = to_minutes(parts[0]) + shift
                work_end = to_minutes(parts[1]) + shift

            if work_start < 0:
                work_start = 0
            if work_end > 24 * 60:
                work_end = 24 * 60
            if work_end < 0:
                work_end = 0
            if work_start > 24 * 60:
                work_start = 24 * 60

            busy = []
            events = info.get("events", [])
            for event in events:
                if event.get("show_as", "busy") != "free":
                    s = to_minutes(event.get("start", "00:00")) + shift
                    e = to_minutes(event.get("end", "00:00")) + shift
                    if e > work_start and s < work_end:
                        if s < work_start:
                            s = work_start
                        if e > work_end:
                            e = work_end
                        if s < e:
                            busy.append([s, e])

            busy = merge_intervals(busy)
            free = free_from_busy(work_start, work_end, busy)

            if first:
                day_free = free
                first = False
            else:
                day_free = intersect_lists(day_free, free)

            if len(day_free) == 0:
                break

        possible = []
        for interval in day_free:
            s = interval[0]
            e = interval[1]
            start = max(s, earliest_min)
            start = ceil_quarter(start)
            limit = min(e, latest_min)
            while start + minutes <= limit:
                possible.append(to_time(start))
                start += 15

        if len(possible) > 0:
            starts[day] = possible

    return {"starts": starts}
