def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def parse_time(text):
        parts = text.split(":")
        return int(parts[0]) * 60 + int(parts[1])

    def format_time(total):
        hours, mins = divmod(total, 60)
        return str(hours).zfill(2) + ":" + str(mins).zfill(2)

    def parse_offset(text):
        sign = 1
        if text and text[0] == "-":
            sign = -1
        hours = int(text[1:3])
        mins = int(text[4:6])
        return sign * (hours * 60 + mins)

    def round_up_quarter(value):
        return ((value + 14) // 15) * 15

    def get_day_record(response):
        day_list = response.get("days", [])
        if len(day_list) == 0:
            return {}
        return day_list[0]

    def get_working_hours(response):
        text = response.get("working_hours", "")
        if "-" not in text:
            return 0, 24 * 60
        parts = text.split("-")
        return parse_time(parts[0]), parse_time(parts[1])

    def convert_interval(start, end, delta):
        return start + delta, end + delta

    def overlaps(a_start, a_end, b_start, b_end):
        return a_start < b_end and a_end > b_start

    result = {"starts": {}}

    if len(days) == 0:
        return result

    earliest_limit = parse_time(earliest) if earliest else 0
    latest_limit = parse_time(latest_end) if latest_end else None

    for day in days:
        user_response = api.read_calendar("", day)
        user_record = get_day_record(user_response)
        user_offset = parse_offset(user_response.get("utc_offset", "+00:00"))
        user_work_start, user_work_end = get_working_hours(user_response)

        busy_intervals = []

        user_events = user_record.get("events", [])
        for event in user_events:
            if event.get("show_as") == "busy":
                start = parse_time(event.get("start", "00:00"))
                end = parse_time(event.get("end", "00:00"))
                busy_intervals.append((start, end))

        common_start = user_work_start
        common_end = user_work_end

        for person in attendees:
            person_response = api.read_calendar(person, day)
            person_record = get_day_record(person_response)
            person_offset = parse_offset(person_response.get("utc_offset", "+00:00"))
            delta = user_offset - person_offset

            person_work_start, person_work_end = get_working_hours(person_response)
            person_work_start, person_work_end = convert_interval(person_work_start, person_work_end, delta)

            if person_work_start > common_start:
                common_start = person_work_start
            if person_work_end < common_end:
                common_end = person_work_end

            pad = 0
            note = person_response.get("note", "")
            note_text = note.lower() if isinstance(note, str) else ""
            if "half an hour" in note_text:
                pad = 30

            person_events = person_record.get("events", [])
            for event in person_events:
                if event.get("show_as") == "busy":
                    start = parse_time(event.get("start", "00:00"))
                    end = parse_time(event.get("end", "00:00"))
                    start, end = convert_interval(start, end, delta)
                    if pad:
                        start -= pad
                        end += pad
                    busy_intervals.append((start, end))

        if latest_limit is not None and latest_limit < common_end:
            common_end = latest_limit
        if earliest_limit > common_start:
            common_start = earliest_limit

        if common_end - minutes < common_start:
            continue

        candidate = round_up_quarter(common_start)
        if candidate < common_start:
            candidate += 15

        workable = []
        last_start = common_end - minutes
        while candidate <= last_start:
            ok = True
            for busy_start, busy_end in busy_intervals:
                if overlaps(candidate, candidate + minutes, busy_start, busy_end):
                    ok = False
                    break
            if ok:
                workable.append(format_time(candidate))
            candidate += 15

        if len(workable) > 0:
            result["starts"][day] = workable

    return result
