def find_shared_starts(api, attendees: list[str], days: list[str], minutes: int,
                       earliest: str = "", latest_end: str = "") -> dict:
    def daykey(text):
        value = text.lower()
        prefix = value[:3]
        if prefix == "mon":
            return "mon"
        if prefix == "tue":
            return "tue"
        if prefix == "wed":
            return "wed"
        if prefix == "thu":
            return "thu"
        return "fri"

    def dayname(text):
        key = daykey(text)
        if key == "mon":
            return "Monday"
        if key == "tue":
            return "Tuesday"
        if key == "wed":
            return "Wednesday"
        if key == "thu":
            return "Thursday"
        return "Friday"

    def to_minutes(text):
        pieces = text.split(":")
        return int(pieces[0]) * 60 + int(pieces[1])

    def from_minutes(value):
        hours, mins = divmod(value, 60)
        hs = str(hours)
        if len(hs) < 2:
            hs = "0" + hs
        ms = str(mins)
        if len(ms) < 2:
            ms = "0" + ms
        return hs + ":" + ms

    def offset_minutes(text):
        sign = 1
        if text[:1] == "-":
            sign = -1
        pieces = text[1:].split(":")
        return sign * (int(pieces[0]) * 60 + int(pieces[1]))

    def parse_hours(text):
        pieces = text.split("-")
        return to_minutes(pieces[0]), to_minutes(pieces[1])

    def convert_interval(start, end, from_offset, to_offset):
        shift = to_offset - from_offset
        return start + shift, end + shift

    def get_day_entry(data, key):
        days_list = data.get("days", [])
        for item in days_list:
            if daykey(item.get("day", "")) == key:
                return item
        if len(days_list) > 0:
            return days_list[0]
        return {"events": []}

    unique_attendees = []
    seen = set()
    for person in attendees:
        if person not in seen:
            seen.add(person)
            unique_attendees.append(person)

    earliest_min = 0 if earliest == "" else to_minutes(earliest)
    latest_min = 24 * 60 if latest_end == "" else to_minutes(latest_end)

    starts = {}

    for day in days:
        key = daykey(day)

        user_data = api.read_calendar("", dayname(day))
        user_offset = offset_minutes(user_data.get("utc_offset", "+00:00"))
        user_entry = get_day_entry(user_data, key)

        windows = []
        user_work_start, user_work_end = parse_hours(user_data.get("working_hours", "00:00-23:59"))
        windows.append((user_work_start, user_work_end))

        busy = []
        for event in user_entry.get("events", []):
            if event.get("show_as", "busy") != "free":
                busy.append((to_minutes(event.get("start", "00:00")),
                             to_minutes(event.get("end", "00:00"))))

        for person in unique_attendees:
            data = api.read_calendar(person, dayname(day))
            person_offset = offset_minutes(data.get("utc_offset", "+00:00"))
            entry = get_day_entry(data, key)

            work_start, work_end = parse_hours(data.get("working_hours", "00:00-23:59"))
            work_start, work_end = convert_interval(work_start, work_end, person_offset, user_offset)
            windows.append((work_start, work_end))

            note = data.get("note", "")
            buffer = 30 if isinstance(note, str) and ("half an hour" in note) and ("other meetings" in note) else 0

            for event in entry.get("events", []):
                if event.get("show_as", "busy") != "free":
                    s = to_minutes(event.get("start", "00:00"))
                    e = to_minutes(event.get("end", "00:00"))
                    s, e = convert_interval(s, e, person_offset, user_offset)
                    busy.append((s - buffer, e + buffer))

        day_starts = []
        for start in range(0, 24 * 60, 15):
            if start < earliest_min:
                continue
            end = start + minutes
            if end > latest_min:
                continue

            ok = True
            for wstart, wend in windows:
                if start < wstart or end > wend:
                    ok = False
                    break
            if not ok:
                continue

            for bstart, bend in busy:
                if start < bend and end > bstart:
                    ok = False
                    break

            if ok:
                day_starts.append(from_minutes(start))

        if len(day_starts) > 0:
            starts[key] = day_starts

    return {"starts": starts}
